            0, 0, 0, 0, 0, 0, 0, 7, 4,
            0, 0, 0, 0, 4, 0, 0, 0, 0
        ];
        let played = [];
        let solved = false;

        cells.forEach(cell => {
            cell.addEventListener('focus', () => {
                cell.classList.toggle('selected');
            });

            cell.addEventListener('blur', () => {
                const value = Number(cell.textContent);
                if (value < 1 || value > 9 || value === 0 && !cell.classList.contains('selected')) {
                    cell.classList.add('invalid');
                } else {
                    cell.classList.remove('invalid');
                    played.push(value);
                }
            });

            document.addEventListener('keydown', e => {
                if (e.keyCode >= 49 && e.keyCode <= 57) {
                    const cell = cells[Array.from(table.rows[e.target.offsetParent.rowIndex].cells).indexOf(e.target)];
                    if (cell.textContent === '') {
                        cell.textContent = e.key;
                        cell.setAttribute('data-value', e.key);
                    }
                }
            });
        });

        function checkSolution() {
            const playedSet = new Set(played);
            const solutionSet = new Set(solution);
            return playedSet.size === solutionSet.size && [...playedSet].every(value => solutionSet.has(value));
        }

        function checkWin() {
            if (!solved) {
                solved = checkSolution();
                cells.forEach(cell => {
                    if (cell.textContent !== solution[Array.from(table.rows).indexOf(cell.parentElement) * 9 + Array.from(cell.parentElement.cells).indexOf(cell) + 1 || !solved) {
                        cell.classList.add('invalid');
                    } else {
                        cell.classList.add('solved');
                    }
                });
            }
        }

        function reset() {
            played = [];
            solved = false;
            cells.forEach(cell => {
                cell.textContent = '';
                cell.setAttribute('data-value', '');
                cell.classList.remove('selected', 'invalid', 'solved');
            });
            checkWin();
        }

        checkWin();
        document.getElementById('reset').addEventListener('click', reset);
    </script>
